CREATE TABLE IF NOT EXISTS src_plm.plm_ecr(id BIGINT NOT NULL AUTO_INCREMENT,ecr_no VARCHAR(32) NOT NULL,ecr_title VARCHAR(200) NOT NULL,product_code VARCHAR(32) NOT NULL,problem_desc VARCHAR(1000) NOT NULL,change_reason VARCHAR(500) NOT NULL,urgency VARCHAR(16) NOT NULL DEFAULT 'NORMAL',proposal VARCHAR(1000) NULL,planned_effective_date DATE NULL,status VARCHAR(16) NOT NULL DEFAULT 'DRAFT',created_by VARCHAR(32) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uk_ecr_no(ecr_no));
CREATE TABLE IF NOT EXISTS src_plm.plm_impact_analysis(id BIGINT NOT NULL AUTO_INCREMENT,ecr_id BIGINT NOT NULL,impact_type VARCHAR(32) NOT NULL,object_code VARCHAR(64) NOT NULL,impact_desc VARCHAR(500) NULL,risk_level VARCHAR(16) NOT NULL DEFAULT 'MEDIUM',cost_impact DECIMAL(18,2) NULL,schedule_impact_days INT NULL,owner_user VARCHAR(32) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(id),KEY idx_impact_ecr(ecr_id));
CREATE TABLE IF NOT EXISTS src_plm.plm_eco(id BIGINT NOT NULL AUTO_INCREMENT,eco_no VARCHAR(32) NOT NULL,ecr_id BIGINT NOT NULL,eco_title VARCHAR(200) NOT NULL,product_code VARCHAR(32) NOT NULL,change_scope VARCHAR(1000) NULL,target_type VARCHAR(16) NOT NULL,target_code VARCHAR(32) NULL,new_version VARCHAR(16) NULL,status VARCHAR(16) NOT NULL DEFAULT 'DRAFT',created_by VARCHAR(32) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uk_eco_no(eco_no));
ALTER TABLE src_plm.plm_ecn ADD COLUMN ecr_id BIGINT NULL AFTER id,ADD COLUMN eco_id BIGINT NULL AFTER ecr_id,ADD COLUMN target_type VARCHAR(16) NULL AFTER change_type,ADD COLUMN target_version VARCHAR(16) NULL AFTER target_type;
INSERT INTO mfg_auth.wf_definition(def_code,def_name,biz_type,description,is_enabled) SELECT 'PLM_ECO_APPROVAL','工程变更命令审批','ECO','研发经理 → 生产主管 → 成本会计',1 WHERE NOT EXISTS(SELECT 1 FROM mfg_auth.wf_definition WHERE biz_type='ECO' AND is_enabled=1);
INSERT INTO mfg_auth.wf_node(definition_id,node_seq,node_name,approver_role,approve_mode,reject_action,remark) SELECT d.id,x.seq,x.name,x.role,'SINGLE','BACK',x.remark FROM mfg_auth.wf_definition d JOIN (SELECT 10 seq,'研发经理审核' name,'RND_MANAGER' role,'确认技术方案' remark UNION ALL SELECT 20,'生产主管审核','PROD_SUPERVISOR','确认生产影响' UNION ALL SELECT 30,'成本审核','COST_ACCOUNTANT','确认成本影响')x WHERE d.biz_type='ECO' AND d.is_enabled=1 AND NOT EXISTS(SELECT 1 FROM mfg_auth.wf_node n WHERE n.definition_id=d.id AND n.node_seq=x.seq);
